import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.D9E58p8B.js";const h=JSON.parse('{"title":"Montrer ce qui se passe","description":"","frontmatter":{"title":"Montrer ce qui se passe"},"headers":[],"relativePath":"agent/montrer.md","filePath":"agent/montrer.md"}'),n={name:"agent/montrer.md"};function s(l,e,i,c,d,u){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="montrer-ce-qui-se-passe" tabindex="-1">Montrer ce qui se passe <a class="header-anchor" href="#montrer-ce-qui-se-passe" aria-label="Permalink to &quot;Montrer ce qui se passe&quot;">​</a></h1><p>Quand un agent agit sur votre écran, vous voulez voir ce qu&#39;il fait. L&#39;Overlay dessine des repères par-dessus l&#39;écran.</p><h2 id="ce-que-vous-demandez" tabindex="-1">Ce que vous demandez <a class="header-anchor" href="#ce-que-vous-demandez" aria-label="Permalink to &quot;Ce que vous demandez&quot;">​</a></h2><blockquote><p>« Montre-moi ce que tu fais pendant que tu remplis le formulaire. »</p></blockquote><h2 id="avant-activer-la-presence-a-l-ecran" tabindex="-1">Avant : activer la présence à l&#39;écran <a class="header-anchor" href="#avant-activer-la-presence-a-l-ecran" aria-label="Permalink to &quot;Avant : activer la présence à l&#39;écran&quot;">​</a></h2><p>L&#39;Overlay est <strong>désactivé par défaut</strong>. Activez <strong>Présence à l&#39;écran</strong> dans le panneau. Tant que ce réglage est coupé, les outils <code>overlay_*</code> répondent <code>ok</code> mais n&#39;affichent rien : l&#39;ordre est abandonné.</p><h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Outil</th><th>Effet</th></tr></thead><tbody><tr><td><a href="/Daimon/reference/overlay.html#overlay-highlight"><code>overlay_highlight</code></a></td><td>Cadre arrondi autour d&#39;une région, avec un libellé</td></tr><tr><td><a href="/Daimon/reference/overlay.html#overlay-spotlight"><code>overlay_spotlight</code></a></td><td>Assombrit l&#39;écran sauf une région</td></tr><tr><td><a href="/Daimon/reference/overlay.html#overlay-cursor"><code>overlay_cursor</code></a></td><td>Halo de curseur</td></tr><tr><td><a href="/Daimon/reference/overlay.html#overlay-banner"><code>overlay_banner</code></a></td><td>Bandeau coloré selon un niveau (<code>L1</code> à <code>L4</code>, <code>gate</code>), avec un texte</td></tr><tr><td><a href="/Daimon/reference/overlay.html#overlay-clear"><code>overlay_clear</code></a></td><td>Efface toutes les marques</td></tr></tbody></table><p>Ces outils sont de la présentation : aucun niveau, aucun effet sur le système. Les coordonnées sont des <strong>pixels globaux</strong>, déjà résolus par l&#39;agent.</p><h2 id="ce-que-vous-obtenez" tabindex="-1">Ce que vous obtenez <a class="header-anchor" href="#ce-que-vous-obtenez" aria-label="Permalink to &quot;Ce que vous obtenez&quot;">​</a></h2><p>Les repères apparaissent sur votre écran pendant que l&#39;agent travaille. <strong>Ils n&#39;apparaissent dans aucune capture d&#39;écran</strong> : c&#39;est voulu, pour que l&#39;agent ne se lise pas lui-même.</p><h2 id="si-rien-n-apparait" tabindex="-1">Si rien n&#39;apparaît <a class="header-anchor" href="#si-rien-n-apparait" aria-label="Permalink to &quot;Si rien n&#39;apparaît&quot;">​</a></h2><ol><li>Vérifiez que <strong>Présence à l&#39;écran</strong> est activée.</li><li>Demandez à l&#39;agent d&#39;appeler <code>daimon_doctor</code> et de lire la clé <code>overlay</code> : <code>listening</code> dit si le processus qui dessine vit et écoute, <code>last_log_line</code> donne sa dernière trace.</li><li>Le processus se relance tout seul au prochain appel tant que la présence est activée. Détail : <a href="/Daimon/reference/overlay.html#helper">Overlay</a>.</li></ol><p>Suite : <a href="/Daimon/agent/deleguer.html">Déléguer à un sous-agent</a>.</p>',14)])])}const v=a(n,[["render",s]]);export{h as __pageData,v as default};
